from pathlib import Path
p = Path("fastapi/exceptions.py")
old = r'''
class RequestValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None) -> None:
        super().__init__(errors)
        self.body = body


class WebSocketRequestValidationError(ValidationException):
    pass


class ResponseValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None) -> None:
        super().__init__(errors)
        self.body = body

    def __str__(self) -> str:
        message = f"{len(self._errors)} validation errors:\n"
        for err in self._errors:
            message += f"  {err}\n"
        return message
'''.lstrip("\n")
new = r'''
class RequestValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None, endpoint_context: Optional[Dict[str, Any]] = None) -> None:
        super().__init__(errors, endpoint_context=endpoint_context)
        self.body = body


class WebSocketRequestValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], endpoint_context: Optional[Dict[str, Any]] = None) -> None:
        super().__init__(errors, endpoint_context=endpoint_context)


class ResponseValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None, endpoint_context: Optional[Dict[str, Any]] = None) -> None:
        super().__init__(errors, endpoint_context=endpoint_context)
        self.body = body

    def __str__(self) -> str:
        message = super().__str__() + ":\n"
        for err in self._errors:
            message += f"  {err}\n"
        return message
'''.lstrip("\n")
s = p.read_bytes().decode()
assert s.count(old) == 1, s.count(old)
s = s.replace(old, new)
if p.suffix == ".py":
    compile(s, str(p), "exec")
p.write_bytes(s.encode())
print("edited", p)
