    import inspect
    def get_endpoint_context(endpoint, path, method):
        try:
            source_file = inspect.getsourcefile(endpoint)
            if source_file:
                lines, start_line = inspect.getsourcelines(endpoint)
                return {
                    "filepath": source_file,
                    "lineno": start_line,
                    "function": endpoint.__name__,
                    "method": method,
                    "path": path,
